# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FOOD PREFERENCES &amp; TASTE ADJECTIVES (YEMEK TERCİHLERİ VE TATLAR)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Expressing Preferences (Tercih Bildirme)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• prefer + Noun / V-ing + to + Noun / V-ing</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#334155">"I prefer cooking pasta to making pizza."</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• would rather + V₁ (yalın fiil) + than + V₁</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11" fill="#334155">"I would rather bake fish than fry it."</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Be fond of / Be keen on / Be crazy about</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" fill="#334155">"She has a sweet tooth; she loves desserts."</text>\n  <text x="180" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">• Can\'t stand (Katlanamamak) / Dislike (Sevmemek)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Taste &amp; Texture Adjectives (Tat Sıfatları)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Sweet (Tatlı) — Chocolate, pudding, cake</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Sour (Ekşi) — Lemon, green plum, vinegar</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Spicy / Hot (Baharatlı / Acı) — Chili pepper, taco</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Salty (Tuzlu) — Salted crackers, pickles</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Bitter (Acı/Buruk) — Dark coffee | Greasy (Yağlı)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Tasty / Delicious / Yummy (Lezzetli) | Milky (Sütlü)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COOKING METHODS &amp; KITCHEN TOOLS (PİŞİRME YÖNTEMLERİ VE ARAÇLAR)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cooking Methods (How do you cook it?)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Bake / Roast: Fırında pişirmek (bread, chicken)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Boil: Suda haşlamak (pasta, eggs, potatoes)</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Fry: Kızgın yağda kızartmak (French fries)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Grill: Izgarada pişirmek (meatballs, steak)</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Steam: Buharda pişirmek (vegetables, broccoli)</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#166534">Sağlıklı yöntemler: Steaming, boiling, grilling</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Preparation Verbs &amp; Kitchen Tools</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Grate (Rendelemek) ➔ Grater (Rende)</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Peel (Kabuk soymak) ➔ Peeler / Knife (Soyacak / Bıçak)</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Drain / Strain (Süzmek) ➔ Strainer (Süzgeç)</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Whisk / Beat (Çırpmak) ➔ Whisk + Bowl (Çırpıcı + Kâse)</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Roll (Hamur açmak) ➔ Rolling pin (Merdane / Oklava)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#475569">Bake (Fırınlamak) ➔ Baking tray &amp; Oven (Tepsi ve Fırın)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">READING &amp; WRITING A COMPLETE RECIPE (TARİF ÇÖZÜMLEME)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Lentil Soup Recipe (Mercimek Çorbası)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">First, peel and chop an onion and a carrot.</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Second, heat some oil in a pot and fry them.</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Next, rinse a cup of red lentils and add them.</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Then, pour five glasses of hot water and boil.</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">After that, blend the mixture until smooth.</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Finally, serve it hot with a slice of lemon.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Key Inquiry Questions (Soru Kalıpları)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• What are the ingredients of lentil soup?</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#334155">(İçindekiler / malzemeler nelerdir?)</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• What is the step after boiling the lentils?</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#334155">(Mercimekleri haşladıktan sonraki adım nedir?)</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• How long does it take to cook it?</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#334155">(Pişirmesi ne kadar sürer? ➔ About 25 minutes.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
